<template><view class="page"><PageScroller :loading="loading" @refresh="load"><view class="list"><view v-for="item in items" :key="item.id" class="card"><view class="card__top"><text class="card__title">{{typeText(item.detectionType)}}</text><text class="priority" :class="item.priority?.toLowerCase()">{{priorityText(item.priority)}}</text><text class="confidence">{{confidence(item.confidence)}}</text></view><image v-if="item.markedUrl||item.evidenceUrl" class="evidence" :src="item.markedUrl||item.evidenceUrl" mode="aspectFill" @click="preview(item)"/><text class="card__meta">通道：{{item.channelId}}\n时间：{{item.createTime}}\n复核：{{statusText(item.status)}} · 处置：{{workflowText(item.workflowStatus)}}\n负责人：{{item.assigneeId||'未分配'}} · 出现：{{item.occurrenceCount||1}} 次</text><view v-if="item.status==='PENDING'" class="review"><button v-if="!item.assigneeId" size="mini" @click="claim(item)">认领</button><button v-if="item.assigneeId&&item.workflowStatus!=='PROCESSING'" size="mini" @click="handle(item,'PROCESSING')">开始处理</button><button size="mini" class="false" @click="review(item,'FALSE_POSITIVE')">标记误报</button><button size="mini" class="confirm" @click="review(item,'CONFIRMED')">确认异常</button></view><button v-else-if="item.alarmId" size="mini" class="alarm" @click="openAlarm(item.alarmId)">查看告警处置</button></view><EmptyState v-if="!loading&&!items.length" title="暂无巡检异常" description="AI 检出的异常会展示在这里"/></view></PageScroller></view></template>
<script setup lang="ts">
import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import PageScroller from'@/components/PageScroller.vue';import EmptyState from'@/components/EmptyState.vue';import{claimInspectionResult,handleInspectionResult,queryInspectionResults,reviewInspectionResult,type InspectionResult}from'@/api/inspection';import{showRequestError}from'@/utils/request';import{useAuthStore}from'@/stores/auth';const auth=useAuthStore(),items=ref<InspectionResult[]>([]),loading=ref(false);async function load(){if(loading.value)return;loading.value=true;try{const r=await queryInspectionResults();items.value=r.list||r.items||[]}catch(e){showRequestError(e)}finally{loading.value=false}}function typeText(v:string){return({BLACK_SCREEN:'画面黑屏',FREEZE:'画面冻结',BLUR:'画面模糊',OCCLUSION:'画面遮挡'}as Record<string,string>)[v]||v}function statusText(v:string){return({PENDING:'待复核',CONFIRMED:'已确认',FALSE_POSITIVE:'误报'}as Record<string,string>)[v]||v}function workflowText(v:string){return({NEW:'待认领',CLAIMED:'已认领',PROCESSING:'处理中',CLOSED:'已关闭'}as Record<string,string>)[v]||v}function priorityText(v:string){return({URGENT:'紧急',HIGH:'重要',NORMAL:'一般'}as Record<string,string>)[v]||v}function confidence(v?:number){return v==null?'--':`${Math.round(v*100)}%`}function preview(i:InspectionResult){const url=i.markedUrl||i.evidenceUrl;if(url)uni.previewImage({urls:[url],current:url})}async function claim(i:InspectionResult){try{Object.assign(i,await claimInspectionResult(i.id))}catch(e){showRequestError(e)}}async function handle(i:InspectionResult,status:'PROCESSING'|'CLOSED'){try{Object.assign(i,await handleInspectionResult(i.id,status))}catch(e){showRequestError(e)}}async function review(i:InspectionResult,status:'CONFIRMED'|'FALSE_POSITIVE'){try{Object.assign(i,await reviewInspectionResult(i.id,status));uni.showToast({title:status==='CONFIRMED'?'已生成告警':'已标记误报',icon:'success'})}catch(e){showRequestError(e)}}function openAlarm(id:number){uni.navigateTo({url:`/pages/alarm/detail?id=${id}`})}onShow(()=>{if(auth.requireAuth())load()})
</script><style lang="scss" scoped>@use '@/styles/list.scss';.page{height:100%;overflow:hidden}.confidence{color:#b54708;font-size:24rpx}.priority{padding:5rpx 10rpx;border-radius:10rpx;background:#edf0f5;font-size:20rpx}.priority.urgent{color:#b42318;background:#fee4e2}.priority.high{color:#b54708;background:#ffead5}.evidence{width:100%;height:280rpx;margin-top:20rpx;background:#edf0f5;border-radius:18rpx}.review{display:flex;justify-content:flex-end;gap:14rpx;margin-top:20rpx;flex-wrap:wrap}.review button,.alarm{margin:0}.false{color:#b54708;background:#ffead5}.confirm,.alarm{color:#2368f2;background:#e9f0ff}.alarm{margin:20rpx 0 0 auto}</style>
